function I(name,size=16){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.sparkles}</svg>`}
const $ = (sel,root=document)=>root.querySelector(sel);
const $$ = (sel,root=document)=>[...root.querySelectorAll(sel)];
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {
  page: (location.hash==='#dashboard'||(TAURI&&WEBVIEW_LABEL==='dashboard')||!TAURI)?'home':'island', settingsTab:'general', islandTab:'home', mood:'', outfit:'', demo:false,
  prefs:loadPrefs(), chats:[], activity:[], pending:[], agentEvents:[], integrationModal:null, chatBusy:false, chatProvider:null,
  apiKeys:{gemini:'',anthropic:'',openai:'',github:''}, githubNotifications:[], toastTimer:null, activityFilter:'all', searchTerm:'', connectedSources:[], hidden:false
};
function loadPrefs(){try{return {...{theme:'blue',glass:78,islandWidth:92,reduceMotion:false,launchAtStartup:false,hideWhenIdle:false,alwaysOnTop:true,notifications:true,sounds:false,permissionSound:true,chatProvider:'gemini',geminiModel:'gemini-2.5-flash',anthropicModel:'claude-3-7-sonnet-latest',openaiModel:'gpt-4o-mini',ollamaModel:'llama3.2',ollamaUrl:'http://localhost:11434',privacyTelemetry:false,confirmDangerous:true,showMascot:true,volume:40,launchGreeting:true,closeToHide:true,autoMood:true,activePill:'Claude Code',quickActions:true,notificationDuration:6,compactMode:true},...JSON.parse(localStorage.getItem('mochi-prefs')||'{}')}}catch{return {theme:'blue',glass:78,islandWidth:92,reduceMotion:false,launchAtStartup:false,hideWhenIdle:false,alwaysOnTop:true,notifications:true,sounds:false,permissionSound:true,chatProvider:'gemini',geminiModel:'gemini-2.5-flash',anthropicModel:'claude-3-7-sonnet-latest',openaiModel:'gpt-4o-mini',ollamaModel:'llama3.2',ollamaUrl:'http://localhost:11434',privacyTelemetry:false,confirmDangerous:true,showMascot:true,volume:40,launchGreeting:true,closeToHide:true,autoMood:true,activePill:'Claude Code',quickActions:true,notificationDuration:6,compactMode:true}}}
function savePrefs(){localStorage.setItem('mochi-prefs',JSON.stringify(state.prefs));applyTheme()}
function applyTheme(){document.documentElement.classList.remove('theme-purple','theme-pink','theme-teal');if(state.prefs.theme!=='blue')document.documentElement.classList.add('theme-'+state.prefs.theme);document.documentElement.style.setProperty('--blur',(8+state.prefs.glass*.28)+'px');document.documentElement.style.setProperty('--island-width',state.prefs.islandWidth+'%');document.documentElement.classList.toggle('reduce-motion',!!state.prefs.reduceMotion);}
function timeAgo(ts){let sec=Math.max(0,Math.floor((Date.now()-ts)/1000));if(sec<5)return'just now';if(sec<60)return`${sec}s ago`;if(sec<3600)return`${Math.floor(sec/60)}m ago`;if(sec<86400)return`${Math.floor(sec/3600)}h ago`;return new Date(ts).toLocaleDateString()}
function addActivity(title,detail='',kind='agent',source='local'){state.activity.unshift({id:crypto.randomUUID?.()||String(Date.now()+Math.random()),title,detail,kind,source,ts:Date.now()});state.activity=state.activity.slice(0,120);}
function toast(msg,type=''){const wrap=$('.toast-wrap');if(!wrap)return;const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;wrap.appendChild(el);setTimeout(()=>el.remove(),3500)}
function openModal(title,body,actions=''){state.integrationModal={title,body,actions};renderModal()}
function closeModal(){state.integrationModal=null;$('#modal-root')?.replaceChildren()}
function renderModal(){let root=$('#modal-root');if(!root)return; if(!state.integrationModal){root.innerHTML='';return} root.innerHTML=`<div class="modal-backdrop" data-action="dismiss-modal"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div class="modal-title">${state.integrationModal.title}</div><button class="icon-button" data-action="close-modal" aria-label="Close">${I('close')}</button></div><div class="modal-body">${state.integrationModal.body}</div>${state.integrationModal.actions?`<div class="modal-actions">${state.integrationModal.actions}</div>`:''}</div></div>`}
function mascotHTML(mood=state.mood,outfit=state.outfit,small=false){return `<div class="mascot-wrap ${small?'small':''}"><span class="mascot-arm left"></span><div class="mascot ${esc(mood||'')}" aria-label="Mochi mascot">${outfit==='party'?'<span class="hat">🎉</span>':''}${outfit==='beanie'?'<span class="hat">🧢</span>':''}${outfit==='crown'?'<span class="hat">👑</span>':''}${outfit==='bunny'?'<span class="hat">🐰</span>':''}${outfit==='bow'?'<span class="hat">🎀</span>':''}${outfit==='pumpkin'?'<span class="hat">🎃</span>':''}${outfit==='glasses'?'<span class="glasses">👓</span>':''}${outfit==='sunglasses'?'<span class="glasses">🕶️</span>':''}${outfit==='scarf'?'<span class="scarf"></span>':''}${outfit==='headphones'?'<span class="headphones"></span>':''}<span class="eye left"></span><span class="eye right"></span><span class="cheek left"></span><span class="cheek right"></span><span class="mouth"></span></div><span class="mascot-arm right"></span>${state.prefs.autoMood?'<span class="mascot-star">✦</span>':''}</div>`}
function statusPill(text,kind='muted'){return `<span class="pill ${kind}"><span class="tiny-dot"></span>${esc(text)}</span>`}
function pageHead(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><div class="page-description">${desc}</div></div><div class="head-actions">${actions}</div></div>`}
const navGroups=[
 {label:'Workspace',items:[['home','Home','home'],['agents','Agent sessions','bot'],['permissions','Permissions','shield'],['chat','AI chat','message'],['activity','Activity log','activity']]},
 {label:'Personalize',items:[['wardrobe','Mascot & wardrobe','palette'],['integrations','Integrations','plug']]},
 {label:'System',items:[['settings','Settings','settings'],['about','About','info']]}
];
function navHTML(){return navGroups.map(g=>`<div class="side-label">${g.label}</div>${g.items.map(([id,label,ic])=>`<button class="nav-item ${state.page===id?'active':''}" data-action="nav" data-page="${id}">${I(ic)}<span>${label}</span>${id==='permissions'&&state.pending.length?`<span class="nav-badge">${state.pending.length}</span>`:''}</button>`).join('')}`).join('')}
function dashboardShell(){return `<div class="app-shell ${state.prefs.theme!=='blue'?'theme-'+state.prefs.theme:''}"><div class="dash-view"><header class="window-top"><div class="brand-lockup"><span class="brand-mark">M</span><span>MOCHI ISLAND</span></div><span class="top-caption">Your tiny desktop companion</span><div class="top-grow"></div><span class="top-status"><span class="status-dot"></span>${TAURI?'Local bridge running':'Browser preview'}</span><div class="window-buttons"><button class="win-btn" data-action="open-island" title="Show island">${I('bot')}</button><button class="win-btn" data-action="minimize-dashboard" title="Minimize">${I('minimize')}</button><button class="win-btn" data-action="close-dashboard" title="Close dashboard">${I('close')}</button></div></header><div class="dash-content"><aside class="sidebar">${navHTML()}<div class="sidebar-spacer"></div><div class="privacy-chip">${I('lock')} Private by design<br>Keys stay in this app session. No telemetry.</div></aside><main class="workspace" id="workspace">${renderPage()}</main></div></div><div class="toast-wrap"></div><div id="modal-root"></div></div>`}
function islandShell(){let online=TAURI?'Local hook bridge':'Preview mode';let subtitle=state.islandTab==='chat'?'Tap to open AI chat':state.pending.length?`${state.pending.length} permission request${state.pending.length===1?'':'s'} waiting`:state.islandTab==='agents'?'Watching for coding agents':'Ready when you need me';return `<div class="app-shell"><div class="island-view"><div class="island-panel glass"><div class="island-nav"><button class="island-action ${state.islandTab==='home'?'active':''}" data-action="island-tab" data-tab="home" title="Home">${I('home',23)}</button><button class="island-action ${state.islandTab==='chat'?'active':''}" data-action="island-tab" data-tab="chat" title="Chat">${I('message',22)}</button><button class="island-action" data-action="quick-add" title="Quick actions">${I('plus',25)}</button><div class="spacer"></div><button class="island-action" data-action="open-settings" title="Settings">${I('settings',22)}</button><button class="island-action" data-action="toggle-sound" title="Toggle sounds">${I('volume',22)}</button><button class="island-action" data-action="open-dashboard" title="Open full dashboard">${I('arrow',21)}</button></div><div class="island-body">${mascotHTML(state.mood,state.outfit)}<div class="island-center"><div class="island-title">${state.islandTab==='chat'?'Talk to Mochi':state.pending.length?'Needs your attention':'Mochi is here'}</div><div class="island-subtitle">${esc(subtitle)}</div><div class="island-mini-actions"><button class="mini-pill" data-action="open-dashboard" data-page="agents">Agent sessions</button><button class="mini-pill" data-action="open-dashboard" data-page="settings">Customize</button></div></div><div class="island-status"><span class="status-dot"></span>${esc(online)}${state.pending.length?` · ${state.pending.length} waiting`:''}</div></div></div><div class="island-bottom"><span>MOCHI ISLAND <span style="opacity:.55">· PERSONAL DESKTOP FRIEND</span></span><span><button data-action="change-mood">Poke Mochi</button> &nbsp;·&nbsp; <button data-action="open-dashboard">Open dashboard ${I('arrow',10)}</button></span></div></div><div class="toast-wrap"></div><div id="modal-root"></div></div>`}
function statCard(ic,label,value,foot,kind='blue'){return `<div class="stat-card"><div class="stat-icon">${I(ic,16)}</div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function activityRows(items){if(!items.length)return `<div class="empty-state"><div class="empty-icon">${I('activity',20)}</div><div class="empty-title">Nothing here yet</div><div class="empty-copy">When you connect an agent or run a demo, its events will appear here. Real events and demo samples are always labeled.</div><button class="btn small" data-action="start-demo">${I('sparkles',13)} Try demo mode</button></div>`;return `<div class="activity-list">${items.map(a=>`<div class="activity-row"><div class="activity-dot">${I(a.kind==='permission'?'shield':a.kind==='chat'?'message':a.kind==='integration'?'plug':'activity',13)}</div><div class="activity-main"><div class="activity-title">${esc(a.title)} ${a.source==='demo'?'<span class="mode-demo">Demo</span>':''}</div><div class="activity-meta">${esc(a.detail||'')} · ${esc(a.source||'local')}</div></div><span class="activity-time">${timeAgo(a.ts)}</span></div>`).join('')}</div>`}
function homePage(){let liveAgents=state.agentEvents.filter(e=>e.source!=='demo').length;let demoLabel=state.demo?'Demo mode is on · no live agents connected':'No live agents connected yet';let waiting=state.pending.length;return `${pageHead('Your workspace','Hey, Mochi is ready ✨','A quiet little island for your AI coding tools. Connect an agent to see real sessions and review permissions without leaving your work.',`<button class="btn subtle" data-action="nav" data-page="settings">${I('settings')} Settings</button><button class="btn primary" data-action="start-demo">${I('sparkles')} ${state.demo?'Refresh demo':'Try a demo'}</button>`)}<div class="grid stats">${statCard('bot','Connected agents',String(new Set(state.agentEvents.filter(e=>e.source!=='demo').map(e=>e.agent||'Claude Code')).size&&state.agentEvents.some(e=>e.source!=='demo')?1:0),state.agentEvents.some(e=>e.source!=='demo')?'Receiving local hook events':'Connect Claude Code first')}${statCard('shield','Waiting permissions',String(waiting),waiting?'Respond in the island':'No approvals waiting','orange')}${statCard('activity','Events today',String(state.activity.filter(a=>new Date(a.ts).toDateString()===new Date().toDateString()).length),state.demo?'Includes labeled demo samples':'Local events only')}${statCard('message','Chat messages',String(state.chats.length),state.apiKeys[state.prefs.chatProvider]?'AI key available for this session':'Set a provider key in Chat settings','purple')}</div><div class="split"><section class="panel"><div class="panel-head"><div><div class="panel-title">Waiting for you</div><div class="panel-subtitle">Tool permissions that need a decision</div></div><button class="text-link" data-action="nav" data-page="permissions">View all ${I('chevron',11)}</button></div>${waiting?state.pending.slice(0,2).map(p=>permissionCard(p,true)).join(''):`<div class="empty-state"><div class="empty-icon">${I('shield',20)}</div><div class="empty-title">All clear for now</div><div class="empty-copy">When Claude Code asks to run a tool, you can review the request right here and choose Allow or Deny.</div><button class="btn small" data-action="nav" data-page="agents">Set up Claude Code ${I('chevron',11)}</button></div>`}</section><section class="panel"><div class="panel-head"><div><div class="panel-title">Recent activity</div><div class="panel-subtitle">A local timeline of agent events</div></div><button class="text-link" data-action="nav" data-page="activity">Open log ${I('chevron',11)}</button></div>${activityRows(state.activity.slice(0,4))}</section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><div class="panel-title">Quick connections</div><div class="panel-subtitle">Set up the tools you use most</div></div><button class="text-link" data-action="nav" data-page="integrations">All integrations ${I('chevron',11)}</button></div><div class="cards-3">${miniConnection('🟠','Claude Code','Real hook bridge','Set up',()=>{})}${miniConnection('🌐','AI Chat','Gemini, Anthropic, OpenAI, Ollama','Configure',()=>{})}${miniConnection('🔗','Custom agent','Post JSON to localhost','View endpoint',()=>{})}</div><div class="footer-note">${esc(demoLabel)}. This app does not report telemetry. Local hook events are received on 127.0.0.1 only.</div></section>`}
function miniConnection(emoji,name,sub,action){return `<div class="integration-card"><div class="card-row"><div class="provider-icon">${emoji}</div><div><div class="provider-name">${name}</div><div class="provider-sub">${sub}</div></div></div><div class="card-bottom"><span class="pill muted">${name==='Claude Code'?(TAURI?'Hook bridge ready':'Desktop app required'):(name==='AI Chat'?'Optional API key':'Local-only endpoint')}</span><button class="btn small" data-action="${name==='Claude Code'?'nav':name==='AI Chat'?'nav':'nav'}" data-page="${name==='Claude Code'?'agents':name==='AI Chat'?'chat':'integrations'}">${action||'Open'}</button></div></div>`}
function permissionCard(p,compact=false){let input=p.tool_input||{};let description=typeof input==='string'?input:(input.command||input.file_path||input.path||input.url||input.description||JSON.stringify(input));return `<div class="permission-card pending"><div class="permission-top"><span class="pill orange">${p.source==='demo'?'DEMO REQUEST':'NEEDS REVIEW'}</span><span class="permission-tool">${esc(p.tool_name||'Tool request')}</span><span class="top-grow"></span><span style="font-size:9px;color:#8e9dc1">${esc(p.session_id||'session')}</span></div><div class="permission-details">${esc(String(description||'The agent is requesting permission to use a tool.').slice(0,compact?155:500))}</div>${!compact?`<div class="footer-note">Hook event: ${esc(p.hook_event_name||'PreToolUse')} · Approving allows this action to continue in the connected agent.</div>`:''}<div class="permission-actions"><button class="btn small subtle" data-action="resolve-permission" data-id="${esc(p.request_id||p.id)}" data-decision="ask">Ask in terminal</button><button class="btn small danger" data-action="resolve-permission" data-id="${esc(p.request_id||p.id)}" data-decision="deny">${I('x',12)} Deny</button><button class="btn small primary" data-action="resolve-permission" data-id="${esc(p.request_id||p.id)}" data-decision="allow">${I('check',12)} Allow once</button></div></div>`}
function agentsPage(){const agents=[['🟠','Claude Code','Live sessions, tool steps, permission approvals','Supported','Real hook bridge'],['⬡','Codex CLI','Session events via custom bridge','Adapter guide','Requires separate hook mapping'],['🟦','Cursor','Terminal & agent activity','Adapter guide','Not auto-detected by default'],['✨','Gemini CLI','Custom hook payload forwarding','Adapter guide','Use /event endpoint'],['🪄','Antigravity','Custom agent event forwarding','Adapter guide','Use /event endpoint'],['⌘','OpenCode','Custom agent event forwarding','Adapter guide','Use /event endpoint']];return `${pageHead('Connections','Agent sessions','Track agent activity and review tool approvals. Claude Code has a real local hook bridge; other tools need a compatible event adapter.',`<button class="btn subtle" data-action="export-events">${I('download')} Export log</button><button class="btn primary" data-action="install-guide">${I('plug')} Set up Claude Code</button>`)}<div class="notice good" style="margin-bottom:14px">${I('lock',14)} <strong>Local-only bridge:</strong> the app listens on 127.0.0.1:49321. It is not exposed to your network. Claude Code tool calls can wait for a decision from this island.</div><div class="cards-3">${agents.map((a,i)=>`<div class="agent-card"><div class="card-row"><div class="provider-icon">${a[0]}</div><div><div class="provider-name">${a[1]}</div><div class="provider-sub">${a[2]}</div></div></div><div style="margin:14px 0 8px">${i===0?statusPill(TAURI?'Hook bridge ready':'Needs desktop app','green'):statusPill(a[3],i===1?'purple':'muted')}</div><div class="card-desc">${a[4]}</div><div class="card-bottom"><span class="provider-sub">${i===0?'PowerShell installer':'Generic adapter'}</span><button class="btn small ${i===0?'primary':'subtle'}" data-action="${i===0?'install-guide':'adapter-guide'}" data-agent="${esc(a[1])}">${i===0?'Configure':'View guide'}</button></div></div>`).join('')}</div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><div class="panel-title">Incoming sessions</div><div class="panel-subtitle">Real hook events and demo events are clearly separated</div></div><div class="head-actions"><button class="btn small" data-action="start-demo">${I('sparkles',12)} Add demo session</button><button class="btn small" data-action="nav" data-page="activity">Activity log</button></div></div>${state.agentEvents.length?`<div class="activity-list">${state.agentEvents.slice(0,10).map(e=>`<div class="activity-row"><div class="activity-dot">${I('terminal',13)}</div><div class="activity-main"><div class="activity-title">${esc(e.summary||e.title||'Agent event')} ${e.source==='demo'?'<span class="mode-demo">Demo</span>':''}</div><div class="activity-meta">${esc(e.session_id||e.sessionId||'unknown session')} · ${esc(e.hook_event_name||e.hookEventName||'AgentEvent')}</div></div><span class="activity-time">${timeAgo(e.ts||Date.now())}</span></div>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">${I('bot',20)}</div><div class="empty-title">No active sessions detected</div><div class="empty-copy">Run the hook installer, then start Claude Code. This section will populate when the agent sends real events.</div><button class="btn small primary" data-action="install-guide">${I('plug',13)} Install hooks</button></div>`}</section>`}
function permissionsPage(){return `${pageHead('Safety','Permission center','Review and decide on agent tool requests. A real Allow or Deny is sent back to Claude Code only for live hook requests.',`<button class="btn subtle" data-action="nav" data-page="agents">${I('bot')} Agent setup</button><button class="btn primary" data-action="permission-demo">${I('shield')} Test permission UI</button>`)}<div class="notice warn" style="margin-bottom:14px">${I('shield',14)} Carefully review the complete command or file path before approving it. Deny sends a denial to the waiting hook; Ask returns the request to the terminal where supported.</div>${state.pending.length?state.pending.map(p=>permissionCard(p)).join(''):`<div class="panel"><div class="empty-state"><div class="empty-icon">${I('shield',20)}</div><div class="empty-title">No pending permissions</div><div class="empty-copy">When a connected agent requests a tool permission, it will stay here until you make a decision or the hook times out.</div><button class="btn small primary" data-action="permission-demo">Create a demo request</button></div></div>`}<section class="panel" style="margin-top:13px"><div class="panel-head"><div><div class="panel-title">Permission behavior</div><div class="panel-subtitle">Configure how Mochi asks for approval</div></div><button class="btn small" data-action="nav" data-page="settings" data-settings-tab="agents">Agent settings</button></div>${settingRow('confirmDangerous','Always require a confirmation for destructive-looking commands','Extra friction is recommended for deletion, install, and deployment commands.',state.prefs.confirmDangerous)}</section>`}
function renderMarkdownLite(text){return esc(text).replace(/`([^`]+)`/g,'<code style="border:1px solid rgba(150,173,255,.2);background:rgba(4,7,19,.6);padding:1px 4px;border-radius:4px">$1</code>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}
function chatPage(){const provider=state.prefs.chatProvider;const providerNames={gemini:'Google Gemini',anthropic:'Anthropic Claude',openai:'OpenAI',ollama:'Ollama (local)'};const ready=provider==='ollama'?true:!!state.apiKeys[provider];let messages=state.chats;return `${pageHead('Assistant','Chat with Mochi','Streaming chat for Gemini, Anthropic, OpenAI, or a local Ollama model. API keys stay in memory for this session and are not saved to disk.',`<button class="btn subtle" data-action="chat-settings">${I('settings')} Provider settings</button><button class="btn" data-action="clear-chat">${I('x')} Clear chat</button>`)}<div class="chat-frame"><div class="chat-toolbar"><div class="kpi-line">${I('sparkles',14)} <strong>${providerNames[provider]}</strong> ${ready?statusPill(provider==='ollama'?'Local endpoint':'Key ready','green'):statusPill('Needs API key','orange')}</div><div class="head-actions"><select class="select" id="chat-provider" aria-label="Chat provider"><option value="gemini" ${provider==='gemini'?'selected':''}>Gemini</option><option value="anthropic" ${provider==='anthropic'?'selected':''}>Anthropic</option><option value="openai" ${provider==='openai'?'selected':''}>OpenAI</option><option value="ollama" ${provider==='ollama'?'selected':''}>Ollama local</option></select></div></div><div class="chat-messages" id="chat-messages">${messages.length?messages.map(m=>`<div class="chat-bubble ${m.role}"><div class="chat-meta">${m.role==='user'?'You':'Mochi'}${m.demo?' · Demo':''}</div>${renderMarkdownLite(m.content)}</div>`).join('')+(state.chatBusy?'<div class="chat-bubble assistant"><div class="chat-meta">Mochi · thinking</div><span class="typing">Thinking…</span></div>':''):`<div class="chat-welcome">${mascotHTML('happy',state.outfit,true)}<div class="page-title" style="font-size:19px;margin-top:10px">Ask Mochi anything</div><div class="page-description" style="margin:7px auto 14px">Coding questions, explanations, debugging ideas, or a little brainstorming. Choose a provider above and add a key in Provider settings.</div><div class="head-actions" style="justify-content:center"><button class="btn small" data-action="chat-prompt" data-prompt="Explain this TypeScript error and give me a minimal fix.">Debug TypeScript</button><button class="btn small" data-action="chat-prompt" data-prompt="Help me plan a small app in clear steps.">Plan an app</button></div></div>`}</div><form class="chat-composer" id="chat-form"><textarea id="chat-input" placeholder="Message Mochi… (Enter to send, Shift+Enter for newline)" aria-label="Message" ${state.chatBusy?'disabled':''}></textarea><button class="btn primary" type="submit" ${state.chatBusy?'disabled':''}>${I('send')} Send</button></form></div><div class="footer-note">Provider calls go directly from this app to the selected provider. Ollama requires a running local server. Some providers may reject browser-style requests depending on API/account settings.</div>`}
function activityPage(){let items=state.activity.filter(a=>state.activityFilter==='all'||a.kind===state.activityFilter).filter(a=>!state.searchTerm||`${a.title} ${a.detail}`.toLowerCase().includes(state.searchTerm.toLowerCase()));return `${pageHead('Timeline','Activity log','A searchable record of local agent events, permission decisions, and chat activity. Export it as JSON when you need a record.',`<button class="btn subtle" data-action="clear-activity">${I('x')} Clear log</button><button class="btn primary" data-action="export-events">${I('download')} Export JSON</button>`)}<div class="panel"><div class="form-row" style="margin-bottom:13px;align-items:center"><div class="field" style="flex:1"><input class="input" id="activity-search" placeholder="Search events…" value="${esc(state.searchTerm)}"></div><div class="activity-filters">${[['all','All'],['permission','Permissions'],['agent','Agent'],['chat','Chat'],['integration','Integrations']].map(([v,l])=>`<button class="filter-chip ${state.activityFilter===v?'active':''}" data-action="activity-filter" data-filter="${v}">${l}</button>`).join('')}</div></div>${items.length?activityRows(items):`<div class="empty-state"><div class="empty-icon">${I('search',20)}</div><div class="empty-title">No events match</div><div class="empty-copy">Change the filter or start a demo to see the activity layout.</div></div>`}</div>`}
function wardrobePage(){let fits=[['none','✨','Classic'],['party','🎉','Party hat'],['beanie','🧢','Beanie'],['crown','👑','Crown'],['bunny','🐰','Bunny ears'],['bow','🎀','Bow'],['glasses','👓','Round glasses'],['sunglasses','🕶️','Sunglasses'],['scarf','🧣','Scarf'],['pumpkin','🎃','Pumpkin'],['headphones','🎧','Headphones']];let moods=[['','Calm'],['happy','Happy'],['love','Love'],['sad','Sad'],['sleep','Sleepy']];return `${pageHead('Personalize','Mochi’s wardrobe','A little character of your own. These expressions and accessories are drawn in the app, using your orange-and-white mascot style.',`<button class="btn subtle" data-action="random-outfit">${I('wand')} Surprise me</button><button class="btn primary" data-action="save-outfit">${I('check')} Apply look</button>`)}<div class="split"><section class="panel" style="display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:245px;background:radial-gradient(ellipse at 50% 65%,rgba(97,123,255,.22),transparent 58%),linear-gradient(135deg,rgba(26,35,76,.7),rgba(9,13,30,.8))">${mascotHTML(state.mood,state.outfit)}<div class="provider-name" style="margin-top:9px">Mochi</div><div class="provider-sub">${esc((fits.find(f=>f[0]===state.outfit)||fits[0])[2])} · ${esc((moods.find(m=>m[0]===state.mood)||moods[0])[1])}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Choose an expression</div><div class="panel-subtitle">Mood changes the mascot's eyes and mouth</div></div></div><div class="cards-2">${moods.map(([v,l])=>`<button class="wardrobe-item ${state.mood===v?'selected':''}" data-action="set-mood" data-mood="${v}"><span class="wardrobe-emoji">${v==='happy'?'😊':v==='love'?'🥰':v==='sad'?'🥺':v==='sleep'?'😴':'🙂'}</span><span class="wardrobe-label">${l}</span></button>`).join('')}</div></section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><div class="panel-title">Accessories</div><div class="panel-subtitle">Choose a hat, glasses, scarf, or headphones</div></div><button class="text-link" data-action="set-outfit" data-outfit="none">Reset look</button></div><div class="wardrobe-grid">${fits.map(([v,em,l])=>`<button class="wardrobe-item ${state.outfit===v?'selected':''}" data-action="set-outfit" data-outfit="${v}"><span class="wardrobe-emoji">${em}</span><span class="wardrobe-label">${l}</span></button>`).join('')}</div></section>`}
function integrationPage(){let rows=[['🟠','Claude Code','Tool use, files, commands, live permission requests','Connected via local hook bridge','agents'],['🤖','Google Gemini','Stream chat and coding help','Chat provider','chat'],['🧠','Anthropic Claude','Stream chat with an Anthropic API key','Chat provider','chat'],['✳','OpenAI','Chat completions API','Chat provider','chat'],['🦙','Ollama','Private local models on your computer','Local endpoint','chat'],['🐙','GitHub','Notifications and repository activity','Token-based preview','github'],['⚡','Stripe','Payment event monitoring','Setup guide only','webhook'],['⛓','n8n','Automation webhooks','Setup guide only','webhook'],['▲','Vercel','Deployment and project alerts','Setup guide only','webhook'],['✉','Resend','Email event workflows','Setup guide only','webhook'],['◉','Notion','Knowledge base workflows','Setup guide only','webhook'],['◷','Cal.com','Scheduling workflows','Setup guide only','webhook'],['🎧','Music','Now-playing UI extension point','Not connected','webhook']];return `${pageHead('Extensions','Integrations','Connect local AI agents and chat providers. Additional service cards are integration guides—not live polling unless the card says otherwise.',`<button class="btn subtle" data-action="custom-endpoint">${I('plus')} Custom event source</button><button class="btn primary" data-action="nav" data-page="agents">${I('bot')} Agent setup</button>`)}<div class="notice" style="margin-bottom:14px">${I('info',14)} Service integrations can require access tokens, webhooks, or server-side endpoints. This app never asks you to paste secret tokens into a public website; API keys entered in Chat are memory-only for this session.</div><div class="integration-grid">${rows.map((r,i)=>`<div class="integration-card"><div class="card-row"><div class="provider-icon">${r[0]}</div><div><div class="provider-name">${r[1]}</div><div class="provider-sub">${r[3]}</div></div></div><div class="card-desc">${r[2]}</div><div class="card-bottom"><span class="pill ${i===0?'green':i>=1&&i<=4?'blue':'muted'}">${i===0?'Local hooks':i>=1&&i<=4?'Available':'Guide / adapter'}</span><button class="btn small ${i===0?'primary':'subtle'}" data-action="${r[4]==='agents'?'install-guide':r[4]==='chat'?'nav':r[4]==='github'?'github-setup':'integration-guide'}" ${r[4]==='chat'?'data-page="chat"':''} data-integration="${esc(r[1])}">${r[4]==='agents'?'Configure':r[4]==='chat'?'Open chat':r[4]==='github'?'Configure':'Setup guide'}</button></div></div>`).join('')}</div>`}
function settingRow(key,title,desc,value){return `<div class="setting-row"><div><div class="setting-title">${title}</div><div class="setting-desc">${desc}</div></div><button class="switch ${value?'on':''}" role="switch" aria-checked="${!!value}" data-action="toggle-pref" data-key="${key}" aria-label="${title}"></button></div>`}
const settingTabs=[['general','General','settings'],['appearance','Appearance','palette'],['agents','Agents & hooks','bot'],['chat','Chat providers','message'],['notifications','Notifications','bell'],['sounds','Sounds','volume'],['shortcuts','Shortcuts','keyboard'],['integrations','Integrations','plug'],['privacy','Privacy','lock'],['about','About','info']];
function settingsMenu(){return `<div class="settings-menu">${settingTabs.map(([v,l,i])=>`<button class="${state.settingsTab===v?'active':''}" data-action="settings-tab" data-tab="${v}">${I(i,14)}<span>${l}</span></button>`).join('')}</div>`}
function settingsGeneral(){return `<div class="setting-card"><div class="panel-head"><div><div class="panel-title">Desktop behavior</div><div class="panel-subtitle">Choose how Mochi behaves on your PC</div></div></div>${settingRow('alwaysOnTop','Keep the island on top','The island window is configured to stay above other windows in the Windows build.',state.prefs.alwaysOnTop)}${settingRow('launchAtStartup','Launch at startup','Preference saved; Windows startup registration needs installer support.',state.prefs.launchAtStartup)}${settingRow('hideWhenIdle','Hide when idle','Hide the island after a quiet period (requires native idle timer integration).',state.prefs.hideWhenIdle)}${settingRow('closeToHide','Close dashboard to hide island','Closing the dashboard window should leave the island available.',state.prefs.closeToHide)}${settingRow('launchGreeting','Show hello animation on launch','Give Mochi a tiny wave when the app opens.',state.prefs.launchGreeting)}${settingRow('quickActions','Show quick actions in island','Keep shortcuts to agent sessions and customization visible.',state.prefs.quickActions)}</div><div class="setting-card"><div class="panel-head"><div><div class="panel-title">Size & interaction</div><div class="panel-subtitle">Small details make the island yours</div></div></div><div class="setting-row"><div><div class="setting-title">Island width</div><div class="setting-desc">Change the compact island width percentage.</div></div><div class="slider-row"><input type="range" min="65" max="100" value="${state.prefs.islandWidth}" data-action="pref-range" data-key="islandWidth"><span class="value-chip">${state.prefs.islandWidth}%</span></div></div>${settingRow('autoMood','Animated mascot accents','Show a tiny sparkle and subtle floating animation.',state.prefs.autoMood)}</div>`}
function settingsAppearance(){return `<div class="setting-card"><div class="panel-head"><div><div class="panel-title">Color theme</div><div class="panel-subtitle">Your custom liquid-glass aesthetic</div></div></div><div class="setting-row"><div><div class="setting-title">Accent colors</div><div class="setting-desc">Blue-purple is based on your reference image. Other palettes are included.</div></div><div class="theme-options">${['blue','purple','pink','teal'].map(t=>`<button class="theme-choice ${state.prefs.theme===t?'selected':''}" data-action="theme" data-theme="${t}" title="${t}"></button>`).join('')}</div></div><div class="setting-row"><div><div class="setting-title">Glass / blur intensity</div><div class="setting-desc">Adjust the translucency style used by the interface.</div></div><div class="slider-row"><input type="range" min="20" max="100" value="${state.prefs.glass}" data-action="pref-range" data-key="glass"><span class="value-chip">${state.prefs.glass}%</span></div></div>${settingRow('showMascot','Show mascot','Display the original orange-and-white mascot in the island.',state.prefs.showMascot)}${settingRow('reduceMotion','Reduce motion','Reduce bounces and continuous animations.',state.prefs.reduceMotion)}</div><div class="setting-card"><div class="panel-title">Mascot</div><div class="setting-desc" style="margin-bottom:12px">Change expression and accessories in the Wardrobe section.</div><button class="btn" data-action="nav" data-page="wardrobe">${I('palette')} Open wardrobe</button></div>`}
function settingsAgents(){return `<div class="setting-card"><div class="panel-head"><div><div class="panel-title">Claude Code hooks</div><div class="panel-subtitle">A local PowerShell bridge for real hook events and permission reviews</div></div><span class="pill ${TAURI?'green':'orange'}">${TAURI?'Bridge configured':'Desktop app required'}</span></div><div class="notice good">The desktop app listens only on <code>127.0.0.1:49321</code>. The installer backs up your existing Claude settings before adding Mochi hooks.</div><div class="code-box" style="margin-top:12px">powershell -ExecutionPolicy Bypass -File .\scripts\install-claude-hooks.ps1</div><div class="head-actions" style="margin-top:10px"><button class="btn primary" data-action="install-guide">${I('plug')} Hook setup guide</button><button class="btn subtle" data-action="copy-install">${I('copy')} Copy command</button><button class="btn subtle" data-action="adapter-guide">Custom event API</button></div></div><div class="setting-card"><div class="panel-title">Safety defaults</div>${settingRow('confirmDangerous','Extra caution for risky-looking commands','UI reminder only; Claude Code permission rules remain the actual security boundary.',state.prefs.confirmDangerous)}${settingRow('notifications','Notify on permission requests','Show an app toast when a new request arrives.',state.prefs.notifications)}</div>`}
function settingsChat(){let provider=state.prefs.chatProvider;return `<div class="setting-card"><div class="panel-head"><div><div class="panel-title">Chat provider</div><div class="panel-subtitle">Keys stay in memory and are cleared when the app reloads</div></div></div><div class="form-stack"><div class="field"><label>Default provider</label><select class="select" id="settings-provider"><option value="gemini" ${provider==='gemini'?'selected':''}>Google Gemini</option><option value="anthropic" ${provider==='anthropic'?'selected':''}>Anthropic Claude</option><option value="openai" ${provider==='openai'?'selected':''}>OpenAI</option><option value="ollama" ${provider==='ollama'?'selected':''}>Ollama (local)</option></select></div><div class="field"><label>${provider==='gemini'?'Gemini API key':provider==='anthropic'?'Anthropic API key':provider==='openai'?'OpenAI API key':'Ollama base URL'}</label><input class="input" id="provider-key" type="${provider==='ollama'?'text':'password'}" placeholder="${provider==='ollama'?'http://localhost:11434':'Paste key for this session only'}" autocomplete="off"><div class="field-note">${provider==='ollama'?'No cloud API key is needed. Ensure Ollama is running locally.':state.apiKeys[provider]?'A key is currently set for this session. The field stays blank to avoid redisplaying it.':'This key is not written to localStorage or included in settings exports.'}</div></div>${provider==='gemini'?`<div class="field"><label>Model</label><input class="input" id="gemini-model" value="${esc(state.prefs.geminiModel)}"></div>`:provider==='anthropic'?`<div class="field"><label>Model</label><input class="input" id="anthropic-model" value="${esc(state.prefs.anthropicModel)}"></div>`:provider==='openai'?`<div class="field"><label>Model</label><input class="input" id="openai-model" value="${esc(state.prefs.openaiModel)}"></div>`:`<div class="field"><label>Model</label><input class="input" id="ollama-model" value="${esc(state.prefs.ollamaModel)}"></div>`}<div class="head-actions"><button class="btn primary" data-action="save-provider">${I('check')} Save for this session</button><button class="btn subtle" data-action="clear-provider-key">Clear key</button><button class="btn" data-action="test-provider">Test connection</button></div></div></div><div class="notice warn">${I('info',14)} API keys entered in a desktop app are still sensitive. This prototype keeps them in JavaScript memory and does not store them, but the secure native keychain integration is not yet implemented.</div>`}
function settingsNotifications(){return `<div class="setting-card"><div class="panel-title">Notifications</div><div class="setting-desc" style="margin-bottom:8px">Control what Mochi calls out to you.</div>${settingRow('notifications','Agent event notifications','Show visual toasts for live events and permissions.',state.prefs.notifications)}${settingRow('permissionSound','Permission request alert','Visual setting placeholder; native system audio requires additional platform packaging.',state.prefs.permissionSound)}<div class="setting-row"><div><div class="setting-title">Toast duration</div><div class="setting-desc">How long in-app toast notices stay visible.</div></div><div class="slider-row"><input type="range" min="2" max="12" value="${state.prefs.notificationDuration}" data-action="pref-range" data-key="notificationDuration"><span class="value-chip">${state.prefs.notificationDuration}s</span></div></div></div>`}
function settingsSounds(){return `<div class="setting-card"><div class="panel-title">Sound & volume</div><div class="setting-desc" style="margin-bottom:8px">Sound controls are configured here; bundled original sound pack can be added separately.</div>${settingRow('sounds','Enable UI sounds','Permit interaction and notification sounds when sound assets are installed.',state.prefs.sounds)}<div class="setting-row"><div><div class="setting-title">Volume</div><div class="setting-desc">Default volume preference for future native sound effects.</div></div><div class="slider-row"><input type="range" min="0" max="100" value="${state.prefs.volume}" data-action="pref-range" data-key="volume"><span class="value-chip">${state.prefs.volume}%</span></div></div><div class="notice">The island volume button toggles the preference. This starter includes no copied sounds from Coucou.</div></div>`}
function settingsShortcuts(){const shortcuts=[['Open / hide island','Ctrl + Alt + Space'],['Open dashboard','Ctrl + Alt + D'],['Open chat','Ctrl + Alt + C'],['Jump to permissions','Ctrl + Alt + A'],['Toggle sound','Ctrl + Alt + M']];return `<div class="setting-card"><div class="panel-title">Keyboard shortcuts</div><div class="setting-desc" style="margin-bottom:8px">Reference shortcut layout. Registering global shortcuts on Windows requires native shortcut plugin wiring.</div>${shortcuts.map(([n,k])=>`<div class="shortcut-row"><div><div class="shortcut-name">${n}</div><div class="shortcut-desc">Default binding</div></div><div class="shortcut-combo">${k.split(' + ').map(x=>`<span class="keyboard-key">${x}</span>`).join('')}</div></div>`).join('')}<div class="footer-note">Global shortcuts are listed as a plan; they are not registered yet in this build.</div></div>`}
function settingsIntegrations(){return `<div class="setting-card"><div class="panel-title">Integration defaults</div><div class="setting-desc" style="margin-bottom:8px">Choose how local and external integrations are handled.</div>${settingRow('privacyTelemetry','Allow anonymous telemetry','Disabled by default. This application currently has no telemetry implementation.',state.prefs.privacyTelemetry)}<div class="setting-row"><div><div class="setting-title">Local event bridge</div><div class="setting-desc">Agent hooks post to 127.0.0.1:49321.</div></div>${statusPill(TAURI?'Running in desktop app':'Unavailable in browser preview',TAURI?'green':'orange')}</div><div class="setting-row"><div><div class="setting-title">Custom agent endpoint</div><div class="setting-desc">Accepts POST /event JSON from local adapters.</div></div><button class="btn small" data-action="adapter-guide">${I('code',12)} View schema</button></div></div>`}
function settingsPrivacy(){return `<div class="setting-card"><div class="panel-title">Privacy & data</div><div class="setting-desc" style="margin-bottom:8px">Built with privacy-first defaults.</div>${settingRow('privacyTelemetry','Anonymous telemetry','No telemetry code is currently included; enabling this preference does not add telemetry.',state.prefs.privacyTelemetry)}<div class="setting-row"><div><div class="setting-title">API key storage</div><div class="setting-desc">Chat API keys exist only in memory for this app session. A native OS keychain is not implemented yet.</div></div><span class="pill green">Memory only</span></div><div class="setting-row"><div><div class="setting-title">Local event bridge</div><div class="setting-desc">Binds exclusively to localhost, not to LAN interfaces.</div></div><span class="pill green">127.0.0.1</span></div><div class="setting-row"><div><div class="setting-title">Exported data</div><div class="setting-desc">Exports include activity records but never include chat API keys.</div></div><button class="btn small" data-action="export-settings">Export preferences</button></div><div class="setting-row"><div><div class="setting-title">Reset settings</div><div class="setting-desc">Reset local preferences and demo state. Does not modify Claude Code settings.</div></div><button class="btn small danger" data-action="reset-settings">Reset</button></div></div>`}
function settingsAbout(){return `<div class="setting-card" style="text-align:center;padding:28px">${mascotHTML('happy',state.outfit)}<div class="page-title" style="font-size:20px;margin-top:10px">Mochi Island</div><div class="page-description" style="margin:7px auto 13px">A custom desktop companion built around your orange-and-white mascot and liquid-glass concept.</div><div class="head-actions" style="justify-content:center"><span class="pill blue">Version 1.0.0</span><span class="pill muted">Original branding</span></div></div><div class="setting-card"><div class="panel-title">Build status</div><div class="setting-row"><div><div class="setting-title">Desktop shell</div><div class="setting-desc">Tauri 2 and Rust project scaffold included.</div></div>${statusPill(TAURI?'Running in Tauri':'Source project','green')}</div><div class="setting-row"><div><div class="setting-title">Claude Code bridge</div><div class="setting-desc">Local HTTP hook receiver and request/response decision flow included.</div></div>${statusPill(TAURI?'Bridge started':'Needs desktop build',TAURI?'green':'orange')}</div><div class="setting-row"><div><div class="setting-title">Other integrations</div><div class="setting-desc">Provider cards, chat adapters, and custom-event schema; several providers need individual adapters.</div></div>${statusPill('Partial','orange')}</div><div class="footer-note">Independent project. Not affiliated with or endorsed by the Coucou project. This app uses its own name, UI, mascot rendering, and no Coucou assets.</div></div>`}
function settingsPage(){const renderers={general:settingsGeneral,appearance:settingsAppearance,agents:settingsAgents,chat:settingsChat,notifications:settingsNotifications,sounds:settingsSounds,shortcuts:settingsShortcuts,integrations:settingsIntegrations,privacy:settingsPrivacy,about:settingsAbout};return `${pageHead('Preferences','Settings','Customize the desktop companion, AI chat, notifications, integrations, and privacy.',`<button class="btn subtle" data-action="export-settings">${I('download')} Export settings</button>`)}<div class="setting-layout">${settingsMenu()}<div>${(renderers[state.settingsTab]||settingsGeneral)()}</div></div>`}
function aboutPage(){return `${pageHead('Project','About Mochi Island','A custom take on a desktop companion, designed for your own mascot and liquid-glass look.',`<button class="btn" data-action="nav" data-page="settings" data-settings-tab="about">${I('settings')} App settings</button>`)}${settingsAbout()}`}
function renderPage(){switch(state.page){case'home':return homePage();case'agents':return agentsPage();case'permissions':return permissionsPage();case'chat':return chatPage();case'activity':return activityPage();case'wardrobe':return wardrobePage();case'integrations':return integrationPage();case'settings':return settingsPage();case'about':return aboutPage();default:return homePage()}}
function render(){applyTheme();const root=$('#app');root.innerHTML=state.page==='island'?islandShell():dashboardShell();if(state.integrationModal)renderModal();if(state.page==='chat')scrollChatEnd();}
function scrollChatEnd(){const m=$('#chat-messages');if(m)m.scrollTop=m.scrollHeight}
function goPage(p){state.page=p;location.hash=p==='home'?'dashboard':p;render()}
function showDashboard(p){if(invoke){invoke('open_dashboard').catch(()=>{state.page=p||'home';render()});return}state.page=p||'home';render()}
function toastFromBody(payload){if(!state.prefs.notifications)return;toast(payload.message||payload.summary||'Mochi received an event',payload.type||'')}
function processIncomingPermission(payload){const p={...payload,source:'live',ts:Date.now(),id:payload.request_id||`live-${Date.now()}`};state.pending.unshift(p);addActivity(`Permission requested: ${p.tool_name||'Tool'}`,p.summary||p.hook_event_name||'PreToolUse','permission','live');state.agentEvents.unshift({...p,ts:Date.now(),source:'live'});render();toast(`Permission needed: ${p.tool_name||'Agent tool'}`,'error')}
function processAgentEvent(payload){let e={...payload,source:'live',ts:Date.now()};state.agentEvents.unshift(e);state.agentEvents=state.agentEvents.slice(0,100);addActivity(e.summary||`${e.hook_event_name||'Agent'} event`,e.tool_name||e.session_id||'Local hook','agent','live');if(state.page!=='island')render();toastFromBody({message:e.summary||'Agent event received'});}
async function resolvePermission(id,decision){let p=state.pending.find(x=>(x.request_id||x.id)===id);if(!p){toast('This request is no longer waiting','error');return}if(p.source==='demo'){state.pending=state.pending.filter(x=>(x.request_id||x.id)!==id);addActivity(`${decision==='allow'?'Allowed':decision==='deny'?'Denied':'Returned to terminal'} demo request`,p.tool_name||'Demo tool','permission','demo');render();toast(`Demo request ${decision==='allow'?'allowed':decision==='deny'?'denied':'returned'}`,'success');return}if(!invoke){toast('Real decisions require the Tauri desktop app.','error');return}try{await invoke('resolve_permission',{args:{requestId:id,decision}});state.pending=state.pending.filter(x=>(x.request_id||x.id)!==id);addActivity(`${decision==='allow'?'Allowed':decision==='deny'?'Denied':'Returned'} ${p.tool_name||'tool request'}`,p.session_id||'Claude Code','permission','live');render();toast(`Request ${decision==='allow'?'allowed':decision==='deny'?'denied':'returned to terminal'}`,'success')}catch(err){toast(String(err),'error')}}
function permissionDemo(){let p={id:`demo-${Date.now()}`,request_id:null,source:'demo',session_id:'demo-session-01',hook_event_name:'PreToolUse',tool_name:'Bash',tool_input:{command:'npm run build && npm test'},summary:'PreToolUse · Bash',ts:Date.now()};state.pending.unshift(p);addActivity('Demo permission request created','Bash · npm run build','permission','demo');render();toast('Demo permission request added (not a live agent action).','success')}
function startDemo(){state.demo=true;const samples=[['Agent started','Claude Code · demo-project','agent'],['Read file','src/App.tsx','agent'],['Edited file','src/components/Island.tsx','agent'],['Ran tests','npm test · passed in 2.1s','agent']];samples.forEach(([t,d,k])=>addActivity(t,d,k,'demo'));state.agentEvents.unshift(...samples.map(([title,detail,kind],i)=>({summary:title,session_id:'demo-session-01',hook_event_name:['SessionStart','PreToolUse','PostToolUse','Stop'][i],tool_name:['','Read','Edit','Bash'][i],source:'demo',ts:Date.now()-i*2000,title,detail})));permissionDemo();state.page='home';render();toast('Demo events added. They are clearly labeled as demo data.','success')}
function getContext(){return state.chats.slice(-20).map(m=>({role:m.role,content:m.content}))}
function pushChat(role,content,extra={}){state.chats.push({role,content,...extra,ts:Date.now()});if(state.chats.length>100)state.chats=state.chats.slice(-100);}
async function streamChat(prompt){let provider=state.prefs.chatProvider;let key=state.apiKeys[provider];if(provider!=='ollama'&&!key){toast('Add the provider API key in Settings → Chat providers first.','error');state.page='settings';state.settingsTab='chat';render();return}state.chatBusy=true;pushChat('user',prompt);let aiIndex=state.chats.length;state.chats.push({role:'assistant',content:'',ts:Date.now()});state.page='chat';render();let assistant=state.chats[aiIndex];try{let messages=state.chats.slice(0,aiIndex).filter(m=>m.role==='user'||m.role==='assistant').slice(-24);let url,headers={'Content-Type':'application/json'},body={};if(provider==='gemini'){url=`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(state.prefs.geminiModel)}:streamGenerateContent?alt=sse`;headers['x-goog-api-key']=key;body={contents:messages.map(m=>({role:m.role==='assistant'?'model':'user',parts:[{text:m.content}]})),generationConfig:{temperature:0.7,maxOutputTokens:2048}}}else if(provider==='anthropic'){url='https://api.anthropic.com/v1/messages';headers['x-api-key']=key;headers['anthropic-version']='2023-06-01';headers['anthropic-dangerous-direct-browser-access']='true';body={model:state.prefs.anthropicModel,max_tokens:2048,stream:true,messages:messages.map(m=>({role:m.role==='assistant'?'assistant':'user',content:m.content}))}}else if(provider==='openai'){url='https://api.openai.com/v1/chat/completions';headers['Authorization']=`Bearer ${key}`;body={model:state.prefs.openaiModel,stream:true,messages:messages.map(m=>({role:m.role,content:m.content}))}}else{url=`${state.prefs.ollamaUrl.replace(/\/$/,'')}/api/chat`;body={model:state.prefs.ollamaModel,stream:true,messages:messages.map(m=>({role:m.role,content:m.content}))}}
 let response=await fetch(url,{method:'POST',headers,body:JSON.stringify(body)});if(!response.ok){let text=await response.text();throw new Error(`Provider returned ${response.status}: ${text.slice(0,300)}`)}const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let chunks=buffer.split(/\r?\n/);buffer=chunks.pop()||'';for(let line of chunks){line=line.trim();if(!line)continue;let data=null;if(provider==='ollama'){try{data=JSON.parse(line)}catch{continue}let piece=data.message?.content||'';if(piece)assistant.content+=piece;if(data.done){} }else if(line.startsWith('data:')){let raw=line.slice(5).trim();if(raw==='[DONE]')continue;try{data=JSON.parse(raw)}catch{continue}let piece='';if(provider==='gemini')piece=data.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'';else if(provider==='openai')piece=data.choices?.[0]?.delta?.content||'';else if(provider==='anthropic'&&data.type==='content_block_delta')piece=data.delta?.text||'';if(piece)assistant.content+=piece;}if(state.page==='chat'){renderChatMessages();}}}if(buffer.trim()&&provider==='ollama'){try{let d=JSON.parse(buffer);assistant.content+=d.message?.content||''}catch{}}if(!assistant.content)assistant.content='(The provider returned no text.)';addActivity('AI chat completed',`${provider} · ${assistant.content.length} characters`,'chat','live');}catch(err){assistant.content=`Could not get a response.

${String(err.message||err)}

Check the provider key/model, internet connection, and API account settings. For Ollama, make sure the local server is running and allows requests from this app.`;addActivity('AI chat failed',String(err.message||err).slice(0,180),'chat','local');toast('Chat request failed. See the response for details.','error')}finally{state.chatBusy=false;render();}}
function renderChatMessages(){const cont=$('#chat-messages');if(!cont)return;cont.innerHTML=state.chats.map(m=>`<div class="chat-bubble ${m.role}"><div class="chat-meta">${m.role==='user'?'You':'Mochi'}</div>${renderMarkdownLite(m.content||'')}${m.role==='assistant'&&state.chatBusy&&state.chats[state.chats.length-1]===m?'<span class="typing">▍</span>':''}</div>`).join('');scrollChatEnd()}
function providerChanged(provider){state.prefs.chatProvider=provider;savePrefs();render()}
function saveProvider(){const p=$('#settings-provider')?.value||state.prefs.chatProvider;state.prefs.chatProvider=p;if(p==='ollama'){const url=$('#provider-key')?.value.trim();if(url)state.prefs.ollamaUrl=url;if($('#ollama-model'))state.prefs.ollamaModel=$('#ollama-model').value.trim()||state.prefs.ollamaModel}else{let v=$('#provider-key')?.value.trim();if(v)state.apiKeys[p]=v;if(p==='gemini'&&$('#gemini-model'))state.prefs.geminiModel=$('#gemini-model').value.trim()||state.prefs.geminiModel;if(p==='anthropic'&&$('#anthropic-model'))state.prefs.anthropicModel=$('#anthropic-model').value.trim()||state.prefs.anthropicModel;if(p==='openai'&&$('#openai-model'))state.prefs.openaiModel=$('#openai-model').value.trim()||state.prefs.openaiModel}savePrefs();toast(p==='ollama'?'Local endpoint settings saved':'Provider saved for this session','success');render()}
async function testProvider(){let p=state.prefs.chatProvider;if(p!=='ollama'&&!state.apiKeys[p]){toast('Enter and save an API key first.','error');return}if(p==='ollama'){try{let r=await fetch(state.prefs.ollamaUrl.replace(/\/$/,'')+'/api/tags');if(!r.ok)throw new Error(`HTTP ${r.status}`);let j=await r.json();toast(`Ollama connected · ${j.models?.length||0} model(s) available`,'success')}catch(e){toast(`Ollama connection failed: ${e.message}`,'error')}return}toast(`${p} key is present for this session. Send a short message to test the full request.`,'success')}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard','success')}catch{openModal('Copy this text',`<textarea class="textarea" readonly>${esc(text)}</textarea>`,`<button class="btn primary" data-action="close-modal">Done</button>`)}}
function installGuide(){let command='powershell -ExecutionPolicy Bypass -File .\\scripts\\install-claude-hooks.ps1';openModal('Set up Claude Code hooks',`<div class="notice good">This installer backs up <code>~/.claude/settings.json</code> before it adds hooks. Existing entries are kept.</div><p>1. Extract the Mochi Island project folder.</p><p>2. Open PowerShell inside the folder.</p><p>3. Run this command:</p><div class="code-box">${esc(command)}</div><p>4. Keep Mochi Island running, then start or continue a Claude Code session. The first PreToolUse request may wait for Allow/Deny in the island.</p><p class="field-note">To remove only Mochi's hook entries, run <code>powershell -ExecutionPolicy Bypass -File .\\scripts\\uninstall-claude-hooks.ps1</code>.</p>`,`<button class="btn" data-action="copy-install">${I('copy')} Copy command</button><button class="btn primary" data-action="close-modal">Got it</button>`)}
function adapterGuide(){let schema=JSON.stringify({hook_event_name:'AgentEvent',session_id:'session-123',tool_name:'Read',tool_input:{file_path:'src/App.tsx'},summary:'Read src/App.tsx'},null,2);openModal('Custom local agent event API',`<p>Send a JSON POST to the local endpoint from a custom agent adapter:</p><div class="code-box">POST http://127.0.0.1:49321/event<br>Content-Type: application/json</div><div class="code-box" style="margin-top:9px">${esc(schema)}</div><p>Health check: <code>GET http://127.0.0.1:49321/health</code>. Generic event posts are logged. For permission blocking, Claude Code uses <code>POST /hook</code> with a <code>PreToolUse</code> event and waits for the returned decision.</p><p class="field-note">The listener binds only to 127.0.0.1. Do not change this to 0.0.0.0 without implementing authentication.</p>`,`<button class="btn" data-action="copy-schema">${I('copy')} Copy JSON schema</button><button class="btn primary" data-action="close-modal">Close</button>`)}
function integrationGuide(name){let content=name==='Stripe'?'Use a server-side webhook forwarder to translate selected Stripe events into Mochi’s local JSON event schema. Never put a Stripe secret key in this desktop frontend.':name==='n8n'?'Create an HTTP Request node that POSTs a JSON summary to http://127.0.0.1:49321/event on the same computer. Remote n8n instances cannot reach your localhost without a secure bridge.':name==='Vercel'?'Use a server-side notification forwarder for deployment events. Do not paste deployment tokens into a public frontend.':name==='Resend'?'Use a server-side webhook receiver to verify Resend signatures and forward a sanitized event summary to the local endpoint.':name==='Notion'?'Use a local or server-side Notion API integration with the minimum required permissions. A full OAuth flow is not included in this starter.':name==='Cal.com'?'Configure Cal.com webhooks to a trusted server-side receiver, then forward sanitized events to the local endpoint.':`${name} can send a sanitized summary event to Mochi's local event API. A dedicated authentication and synchronization adapter is not included yet.`;openModal(`${name} setup guide`,`<div class="notice warn">Guide only — this service is not connected live in this starter.</div><p>${esc(content)}</p><button class="btn" data-action="adapter-guide">View custom event schema</button>`,`<button class="btn primary" data-action="close-modal">Close</button>`)}
function customEndpoint(){openModal('Add a custom agent',`<p>Custom adapters can send activity to the local bridge.</p><div class="form-stack"><div class="field"><label>Agent name</label><input class="input" id="custom-agent-name" placeholder="My CLI agent"></div><div class="field"><label>Event type</label><input class="input" id="custom-agent-event" value="AgentEvent"></div></div><div class="field-note" style="margin-top:10px">After creating the connection note, use the endpoint schema to forward safe, non-secret event summaries.</div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-custom-agent">Add adapter</button>`)}
function githubSetup(){openModal('GitHub notifications (session-only token)',`<p>Use a personal access token with read-only notifications access. The token will remain in memory only and will not be saved.</p><div class="field"><label>GitHub token</label><input class="input" id="github-token" type="password" placeholder="github_pat_…" autocomplete="off"></div><div class="field-note" style="margin-top:8px">Use the minimum read-only permissions required. The app will request /notifications from api.github.com.</div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="connect-github">${I('plug')} Connect and fetch</button>`)}
async function connectGithub(){let token=$('#github-token')?.value.trim();if(!token){toast('Add your GitHub token first.','error');return}state.apiKeys.github=token;try{let r=await fetch('https://api.github.com/notifications?per_page=10',{headers:{Authorization:`Bearer ${token}`,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'}});if(!r.ok)throw new Error(`GitHub returned ${r.status}: ${(await r.text()).slice(0,150)}`);state.githubNotifications=await r.json();addActivity('GitHub notifications refreshed',`${state.githubNotifications.length} unread notifications`,'integration','live');closeModal();render();toast(`GitHub connected · ${state.githubNotifications.length} notifications`, 'success')}catch(e){toast(`GitHub connection failed: ${e.message}`,'error')}}
function exportJSON(obj,filename){let blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);toast('Export downloaded','success')}
function actionHandler(e){const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;const page=b.dataset.page;const id=b.dataset.id;const decision=b.dataset.decision;
 if(a==='nav'){state.page=page||'home';if(b.dataset.settingsTab)state.settingsTab=b.dataset.settingsTab;location.hash=state.page==='home'?'dashboard':state.page;render()}
 else if(a==='settings-tab'){state.settingsTab=b.dataset.tab;render()}
 else if(a==='island-tab'){state.islandTab=b.dataset.tab;render()}
 else if(a==='open-dashboard'){showDashboard(b.dataset.page||'home')}
 else if(a==='open-settings'){showDashboard('settings')}
 else if(a==='open-island'){if(invoke){invoke('show_island').catch(()=>{});toast('Island shown','success')}else{state.page='island';render()}}
 else if(a==='close-dashboard'){if(TAURI?.webviewWindow?.getCurrentWebviewWindow){TAURI.webviewWindow.getCurrentWebviewWindow().close().catch(()=>{});}else{state.page='island';render()}}
 else if(a==='minimize-dashboard'){if(TAURI?.webviewWindow?.getCurrentWebviewWindow)TAURI.webviewWindow.getCurrentWebviewWindow().minimize().catch(()=>{});else toast('Minimize is available in the desktop build')}
 else if(a==='quick-add'){openModal('Quick actions',`<div class="cards-2"><button class="wardrobe-item" data-action="nav" data-page="chat"><span class="wardrobe-emoji">💬</span><span class="wardrobe-label">Start a chat</span></button><button class="wardrobe-item" data-action="nav" data-page="agents"><span class="wardrobe-emoji">🤖</span><span class="wardrobe-label">Agent sessions</span></button><button class="wardrobe-item" data-action="nav" data-page="wardrobe"><span class="wardrobe-emoji">🎨</span><span class="wardrobe-label">Change Mochi</span></button><button class="wardrobe-item" data-action="nav" data-page="settings"><span class="wardrobe-emoji">⚙️</span><span class="wardrobe-label">Settings</span></button></div>`,`<button class="btn" data-action="close-modal">Close</button>`)}
 else if(a==='toggle-sound'){state.prefs.sounds=!state.prefs.sounds;savePrefs();toast(`UI sounds ${state.prefs.sounds?'enabled':'disabled'} (sound assets are not bundled)`);render()}
 else if(a==='change-mood'){let moods=['happy','love','sad','sleep',''];state.mood=moods[(moods.indexOf(state.mood)+1)%moods.length];render()}
 else if(a==='start-demo')startDemo()
 else if(a==='permission-demo')permissionDemo()
 else if(a==='resolve-permission')resolvePermission(id,decision)
 else if(a==='install-guide')installGuide()
 else if(a==='copy-install')copyText('powershell -ExecutionPolicy Bypass -File .\\scripts\\install-claude-hooks.ps1')
 else if(a==='adapter-guide')adapterGuide()
 else if(a==='custom-endpoint')customEndpoint()
 else if(a==='integration-guide')integrationGuide(b.dataset.integration||'Integration')
 else if(a==='github-setup')githubSetup()
 else if(a==='connect-github')connectGithub()
 else if(a==='clear-chat'){state.chats=[];render();toast('Chat history cleared','success')}
 else if(a==='chat-settings'){state.page='settings';state.settingsTab='chat';render()}
 else if(a==='chat-prompt'){state.page='chat';render();setTimeout(()=>{const input=$('#chat-input');if(input){input.value=b.dataset.prompt;input.focus()}},0)}
 else if(a==='save-provider')saveProvider()
 else if(a==='clear-provider-key'){let p=state.prefs.chatProvider;if(p==='ollama'){state.prefs.ollamaUrl='http://localhost:11434'}else state.apiKeys[p]='';savePrefs();render();toast('Current provider credential cleared from memory')}
 else if(a==='test-provider')testProvider()
 else if(a==='export-events')exportJSON({app:'Mochi Island',version:'1.0.0',exportedAt:new Date().toISOString(),events:state.activity,agentEvents:state.agentEvents,pending:state.pending.map(({raw,...p})=>p)},'mochi-island-activity.json')
 else if(a==='export-settings')exportJSON({...state.prefs,apiKeys:'Not exported'},'mochi-island-settings.json')
 else if(a==='clear-activity'){if(confirm('Clear all local activity records?')){state.activity=[];state.agentEvents=[];render();toast('Activity log cleared')}}
 else if(a==='activity-filter'){state.activityFilter=b.dataset.filter;render()}
 else if(a==='theme'){state.prefs.theme=b.dataset.theme;savePrefs();render()}
 else if(a==='toggle-pref'){let key=b.dataset.key;state.prefs[key]=!state.prefs[key];savePrefs();if(key==='alwaysOnTop'&&invoke)invoke('set_always_on_top',{enabled:state.prefs[key]}).catch(err=>toast(String(err),'error'));render()}
 else if(a==='set-mood'){state.mood=b.dataset.mood;render()}
 else if(a==='set-outfit'){state.outfit=b.dataset.outfit;render()}
 else if(a==='random-outfit'){let fits=['none','party','beanie','crown','bunny','bow','glasses','sunglasses','scarf','pumpkin','headphones'];let moods=['','happy','love','sleep'];state.outfit=fits[Math.floor(Math.random()*fits.length)];state.mood=moods[Math.floor(Math.random()*moods.length)];render();toast('A fresh look for Mochi','success')}
 else if(a==='save-outfit'){toast('Mochi’s look applied for this session','success')}
 else if(a==='copy-schema')copyText(JSON.stringify({hook_event_name:'AgentEvent',session_id:'session-123',tool_name:'Read',tool_input:{file_path:'src/App.tsx'},summary:'Read src/App.tsx'},null,2))
 else if(a==='save-custom-agent'){let name=$('#custom-agent-name')?.value.trim()||'Custom agent';addActivity(`Added custom adapter: ${name}`,$('#custom-agent-event')?.value||'AgentEvent','integration','local');closeModal();render();toast('Custom adapter note added','success')}
 else if(a==='dismiss-modal'&&e.target===b)closeModal()
 else if(a==='close-modal')closeModal()
 else if(a==='reset-settings'){if(confirm('Reset all Mochi Island preferences?')){localStorage.removeItem('mochi-prefs');state.prefs=loadPrefs();state.apiKeys={gemini:'',anthropic:'',openai:'',github:''};state.demo=false;state.outfit='';state.mood='';render();toast('Preferences reset','success')}}
}
function onChangeHandler(e){const t=e.target;if(t.id==='chat-provider'){providerChanged(t.value)}if(t.id==='settings-provider'){state.prefs.chatProvider=t.value;savePrefs();render()}if(t.dataset.action==='pref-range'){state.prefs[t.dataset.key]=Number(t.value);savePrefs();const chip=t.parentElement.querySelector('.value-chip');if(chip)chip.textContent=t.dataset.key==='notificationDuration'?`${t.value}s`:t.dataset.key==='volume'?`${t.value}%`:t.dataset.key==='islandWidth'?`${t.value}%`:`${t.value}%`;const val=t.value; if(t.dataset.key==='glass')document.documentElement.style.setProperty('--blur',val+'px') }}
function eventListeners(){const root=$('#app');root.addEventListener('click',actionHandler);root.addEventListener('change',onChangeHandler);root.addEventListener('input',e=>{if(e.target.id==='activity-search'){state.searchTerm=e.target.value;const pos=e.target.selectionStart;const area=e.target;const oldScroll=$('.workspace')?.scrollTop;render();const next=$('#activity-search');if(next){next.focus();next.setSelectionRange(pos,pos)}if($('.workspace')&&oldScroll!==undefined)$('.workspace').scrollTop=oldScroll}});root.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();const input=$('#chat-input');const val=input?.value.trim();if(val&&!state.chatBusy){streamChat(val)}}});root.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form')?.requestSubmit()}if(e.key==='Escape'&&state.integrationModal)closeModal()});}
function setupTauriEvents(){if(!TAURI?.event?.listen)return;TAURI.event.listen('permission-request',e=>processIncomingPermission(e.payload));TAURI.event.listen('agent-event',e=>processAgentEvent(e.payload));TAURI.event.listen('hook-server-error',e=>toast(`Hook server error: ${e.payload}`,'error'));}
function setupDragDrop(){document.addEventListener('dragover',e=>{e.preventDefault()});document.addEventListener('drop',e=>{if(e.target.closest('input,textarea,[contenteditable="true"]'))return;e.preventDefault();const files=[...(e.dataTransfer?.files||[])];if(!files.length)return;let names=files.map(f=>f.name).join(', ');addActivity('File dropped on Mochi',names,'integration','local');openModal('Files received',`<p>Received ${files.length} file(s):</p><div class="code-box">${esc(names)}</div><p>In this starter, files are logged locally only. File contents are not uploaded automatically.</p>`,`<button class="btn primary" data-action="close-modal">Close</button>`);})}
function boot(){applyTheme();eventListeners();setupTauriEvents();setupDragDrop();render();if(state.prefs.launchGreeting){state.mood='happy';setTimeout(()=>{if(state.page==='island')render()},600)}if(TAURI&&state.page!=='island'&&location.hash!=='#dashboard')state.page='island';if(state.page==='island'&&!TAURI){state.page='home';render()} }
boot();
